package com.creatorhub.model; public class Student {private int studentId; private String name,email,passwordHash,roleTitle,aboutMe,skills,workText; public int getStudentId(){return studentId;} public void setStudentId(int v){studentId=v;} public String getName(){return name;} public void setName(String v){name=v;} public String getEmail(){return email;} public void setEmail(String v){email=v;} public String getPasswordHash(){return passwordHash;} public void setPasswordHash(String v){passwordHash=v;} public String getRoleTitle(){return roleTitle;} public void setRoleTitle(String v){roleTitle=v;} public String getAboutMe(){return aboutMe;} public void setAboutMe(String v){aboutMe=v;} public String getSkills(){return skills;} public void setSkills(String v){skills=v;} public String getWorkText(){return workText;} public void setWorkText(String v){workText=v;}}
